"""Generic tools (spec "Tools"). S2: drills, generated by rule from config/tools.toml; S3: end mills."""

from __future__ import annotations

from dataclasses import dataclass

from . import settings
from .units import METRIC, MM_PER_IN


@dataclass(frozen=True)
class Drill:
    diameter_mm: float
    label: str  # "17/64 in" style is built by the caller; this is "6.5 mm" or "0.2656 in"
    metric: bool


def _steps(start: float, stop: float, step: float) -> list[float]:
    n = round((stop - start) / step)
    return [round(start + i * step, 6) for i in range(n + 1)]


def drills(units_in_file: str) -> list[Drill]:
    """The drill set for a part: 1/64 in drills for inch, other and no-unit files; for metric files
    (mm, cm, m: D-020), metric drills plus the 1/64 in drills, because inch-designed parts are often
    exported in mm (D-013)."""
    cfg = settings.tools_config()["drills"]
    inch = [Drill(d * MM_PER_IN, f"{d:.4f} in", False)
            for r in cfg["inch"] for d in _steps(r["from_in"], r["to_in"], r["step_in"])]
    if units_in_file not in METRIC:
        return inch
    metric = [Drill(d, f"{d:g} mm", True) for r in cfg["mm"] for d in _steps(r["from_mm"], r["to_mm"], r["step_mm"])]
    return metric + inch


def match_tolerance_mm() -> float:
    return settings.tools_config()["drills"]["match_tolerance_in"] * MM_PER_IN


def nearest_drill(diameter_mm: float, units_in_file: str) -> Drill:
    """The closest drill; a tie (to 1e-6 mm) goes to the smaller drill."""
    return min(drills(units_in_file), key=lambda d: (round(abs(d.diameter_mm - diameter_mm), 6), d.diameter_mm))


def drill_range_mm(units_in_file: str) -> tuple[float, float]:
    sizes = [d.diameter_mm for d in drills(units_in_file)]
    return min(sizes), max(sizes)


PICK_TOL_MM = 0.001  # a corner radius equal to a tool's radius fits (spec S3 "Settled at build")


def end_mills_mm() -> list[float]:
    """The inch end-mill list, in mm, smallest first. Every file uses it (no metric end mills yet)."""
    return sorted(d * MM_PER_IN for d in settings.tools_config()["end_mills"]["inch"])


def pick_end_mill(min_corner_radius: float, narrowest_width: float) -> tuple[float, bool]:
    """The largest end mill (diameter, mm) whose radius is at most the corner radius and whose
    diameter is at most the width; when none fits, the smallest, with undersized True."""
    mills = end_mills_mm()
    fits = [d for d in mills if d / 2 <= min_corner_radius + PICK_TOL_MM and d <= narrowest_width + PICK_TOL_MM]
    return (fits[-1], False) if fits else (mills[0], True)
